class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        target = len(nums) - k                   # index of the answer in sorted order
        lo, hi = 0, len(nums) - 1
        while True:
            pivot = nums[random.randint(lo, hi)]  # a random pivot avoids the sorted-input worst case
            lt, i, gt = lo, lo, hi                # three-way partition: < pivot | == pivot | > pivot
            while i <= gt:
                if nums[i] < pivot:
                    nums[lt], nums[i] = nums[i], nums[lt]
                    lt += 1
                    i += 1
                elif nums[i] > pivot:
                    nums[gt], nums[i] = nums[i], nums[gt]
                    gt -= 1
                else:
                    i += 1
            if target < lt:                       # keep only the side that holds the target
                hi = lt - 1
            elif target > gt:
                lo = gt + 1
            else:
                return nums[target]
